import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict with side, price, qty, arrival, active
    arrival_counter = 0

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        arrival = arrival_counter
        arrival_counter += 1
        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        def can_match(p, side=side, typ=typ, price=price):
            if typ == 'market':
                return True
            if side == 'buy':
                return p <= price
            else:
                return p >= price

        while remaining > 0 and heap:
            top = heap[0]
            top_price = -top[0] if side == 'buy' else top[0]
            top_id = top[2]
            resting = book.get(top_id)
            if resting is None or not resting['active'] or resting['qty'] <= 0:
                heapq.heappop(heap)
                continue
            if not can_match(top_price):
                break
            heapq.heappop(heap)
            trade_qty = min(remaining, resting['qty'])
            resting['qty'] -= trade_qty
            remaining -= trade_qty
            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])
            if resting['qty'] > 0:
                heapq.heappush(heap, top)
            else:
                resting['active'] = False

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        else:
            if oid not in book:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'arrival': arrival, 'active': False}
            else:
                book[oid]['active'] = False

    return trades

